// HTTP API includes the stage name as a path prefix for any named stage
// (dev/test/prod), but NOT for $default. Strip it so route matching in each
// grouped-resource Lambda is stage-independent.
function normalizePath(event) {
  const stage = event.requestContext.stage;
  let path = event.requestContext.http.path;

  if (stage && stage !== "$default" && path.startsWith(`/${stage}`)) {
    path = path.slice(stage.length + 1) || "/";
  }

  return path;
}

module.exports = { normalizePath };